import type { CSSProperties } from "react";

// Generated by strokit. Colors follow --sk-stroke; prefers-reduced-motion shows the final frame.
const css = `
.sk-e14m9w-0 {
  transform-box: fill-box;
  transform-origin: center;
  animation: sk-e14m9w-t0-pulse calc(1400ms / var(--sk-speed, 1)) ease-in-out 0ms var(--sk-iterations, infinite) normal both;
  animation-play-state: var(--sk-play-state, running);
}
@keyframes sk-e14m9w-t0-pulse {
  0% {
    opacity: 1;
    transform: scale(1);
  }
  50% {
    opacity: 0.5;
    transform: scale(1.06);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sk-e14m9w * {
    animation: none;
  }
  .sk-e14m9w-0 {
    opacity: 1;
    transform: none;
  }
}
`;

export type OrbitaPulseProps = {
  /** Width and height (number = px). Defaults to the SVG's own size. */
  size?: number | string;
  /** Playback speed multiplier: 2 plays twice as fast. */
  speed?: number;
  /** true repeats forever, false plays once. Defaults to the exported animation. */
  loop?: boolean;
  paused?: boolean;
  className?: string;
  /** Accessible name. Defaults to "Órbita". */
  label?: string;
};

export function OrbitaPulse({
  size,
  speed = 1,
  loop,
  paused = false,
  className,
  label = "Órbita",
}: OrbitaPulseProps) {
  const style = {
    "--sk-speed": speed,
    "--sk-play-state": paused ? "paused" : "running",
    ...(loop === undefined ? {} : { "--sk-iterations": loop ? "infinite" : 1 }),
  } as CSSProperties;

  return (
    <svg
      viewBox="0 0 160 160"
      width={size ?? 160}
      height={size ?? 160}
      className={className ? `sk-e14m9w ${className}` : "sk-e14m9w"}
      style={style}
      role="img"
      aria-label={label}
    >
      <style>{css}</style>
      <title>{"Órbita"}</title>
      <g fill="none" stroke="#4f46e5" strokeWidth="6" strokeLinecap="round" strokeLinejoin="round">
        <circle cx="80" cy="80" r="58" className="sk-e14m9w-0" />
        <g transform="rotate(-28 80 80)">
          <ellipse cx="80" cy="80" rx="72" ry="26" stroke="#a5b4fc" strokeWidth="4" className="sk-e14m9w-0" />
        </g>
        <path d="M58 92 C 62 70, 76 60, 98 62" className="sk-e14m9w-0" />
        <circle cx="126" cy="46" r="9" stroke="#f59e0b" className="sk-e14m9w-0" />
      </g>
    </svg>
  );
}
